void PrintDetailedType(Assembly assembly, string ns, string typeName)
{
    var type = assembly.GetType($"{ns}.{typeName}");
    if (type == null)
    {
        Console.WriteLine($"✗ {ns}.{typeName} not found");
        return;
    }

    Console.WriteLine($"✓ {ns}.{typeName}");

    var ctors = type.GetConstructors(BindingFlags.Public | BindingFlags.Instance);
    if (ctors.Length > 0)
    {
        Console.WriteLine("  Constructors:");
        foreach (var ctor in ctors)
        {
            var parms = string.Join(", ", ctor.GetParameters().Select(p => $"{GetShortTypeName(p.ParameterType)} {p.Name}"));
            Console.WriteLine($"    public {typeName}({parms})");
        }
    }
    else
    {
        Console.WriteLine("  (No public constructors)");
    }

    var props = type.GetProperties(BindingFlags.Public | BindingFlags.Instance);
    if (props.Length > 0)
    {
        Console.WriteLine("  Properties:");
        foreach (var prop in props.OrderBy(p => p.Name))
        {
            var access = (prop.CanRead && prop.CanWrite) ? "{ get; set; }" : (prop.CanRead ? "{ get; }" : "{ set; }");
            Console.WriteLine($"    {GetShortTypeName(prop.PropertyType)} {prop.Name} {access}");
        }
    }

    var methods = type.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly)
        .Where(m => !m.IsSpecialName)
        .ToList();
    if (methods.Count > 0)
    {
        Console.WriteLine("  Methods:");
        foreach (var method in methods.Take(15).OrderBy(m => m.Name))
        {
            var parms = string.Join(", ", method.GetParameters().Select(p => $"{GetShortTypeName(p.ParameterType)} {p.Name}"));
            Console.WriteLine($"    {GetShortTypeName(method.ReturnType)} {method.Name}({parms})");
        }
        if (methods.Count > 15)
            Console.WriteLine($"    ... and {methods.Count - 15} more methods");
    }

    Console.WriteLine();
}

string GetShortTypeName(Type type)
{
    if (type.IsGenericType)
    {
        var baseName = type.Name.Split('`')[0];
        var args = type.GetGenericArguments();
        if (args.Length == 1)
            return $"{baseName}<{GetShortTypeName(args[0])}>";
        else
            return $"{baseName}<{string.Join(", ", args.Select(GetShortTypeName))}>";
    }
    if (type.Name == "Void") return "void";
    return type.Name;
}
