+builder.Services.AddChatClient(b => b
+    .UseOpenAIChatClient(modelId));
+builder.Services.AddSingleton<ResearchTools>();
+
+var host = builder.Build();
+
+var chatClient = host.Services.GetRequiredService<IChatClient>();
+var loggerFactory = host.Services.GetRequiredService<ILoggerFactory>();
+var researchTools = host.Services.GetRequiredService<ResearchTools>();
+
+var tools = new AITool[]
+{
+    AIFunctionFactory.Create(researchTools.SearchWebAsync),
+    AIFunctionFactory.Create(researchTools.SaveNote),
+    AIFunctionFactory.Create(researchTools.GetNotes),
+};
+
+var agentOptions = new ChatClientAgentOptions
+{
+    Name = "ResearchAgent",
+    Description = "An AI agent that researches topics by searching the web and taking notes.",
+    ChatOptions = new ChatOptions
+    {
+        Tools = [.. tools],
+        ToolMode = ChatToolMode.Auto,
+        Temperature = 0f,
+        MaxOutputTokens = 4096,
+    },
+};
+
+var agent = new ChatClientAgent(chatClient, agentOptions, loggerFactory, host.Services);
+var session = await agent.CreateSessionAsync();
+
+var topic = args.Length > 0
+    ? string.Join(' ', args)
+    : PromptForTopic();
+
+Console.WriteLine($"\n🔍 Researching: {topic}\n");
+
+var systemPrompt = $"""
+    You are a research assistant. Your goal is to thoroughly research the following topic
+    and produce a well-organized summary.
+
+    **Workflow:**
+    1. Search the web for information on the topic using multiple queries to cover
+       different aspects.
+    2. As you find useful information, save key findings as notes using the note-taking tool.
+    3. After gathering enough information (at least 3 searches), retrieve your notes
+       and write a comprehensive summary.
+
+    **Topic:** {topic}
+
+    Begin by searching for the topic now.
+    """;
+
+var runOptions = new ChatClientAgentRunOptions(new ChatOptions
+{
+    Temperature = 0f,
+    MaxOutputTokens = 4096,
+});
+
+Console.WriteLine("⏳ Agent is working...\n");
+
+await foreach (var update in agent.RunStreamingAsync(
+    new ChatMessage(ChatRole.User, systemPrompt),
+    session,
+    runOptions))
+{
+    if (!string.IsNullOrEmpty(update.Text))
+    {
+        Console.Write(update.Text);
+    }
+}
+
+Console.WriteLine("\n\n--- Notes collected during research ---");
+foreach (var note in researchTools.GetAllNotes())
+{
+    Console.WriteLine($"  • {note}");
+}
+
+Console.WriteLine("\n✅ Research complete.");
+
+static string PromptForTopic()
+{
+    Console.Write("Enter a research topic: ");
+    var input = Console.ReadLine()?.Trim();
+    return string.IsNullOrEmpty(input)
+        ? "Recent advances in quantum computing 2026"
+        : input;
+}
+
+/// <summary>
+/// Provides web search and note-taking tools for the research agent.
+/// </summary>
+sealed class ResearchTools
+{
+    private readonly List<string> _notes = [];
+    private readonly HttpClient _httpClient = new()
+    {
+        DefaultRequestHeaders =
+        {
+            { "User-Agent", "ResearchAgent/1.0" },
+            { "Accept", "text/html" },
+        },
+        Timeout = TimeSpan.FromSeconds(15),
+    };
+
+    [Description("Search the web for information on a query. Returns a list of search result snippets.")]
+    public async Task<string> SearchWebAsync(
+        [Description("The search query string")] string query,
+        CancellationToken cancellationToken = default)
+    {
+        Console.WriteLine($"  🌐 Searching: \"{query}\"");
+
+        try
+        {
+            // Use DuckDuckGo Lite as a simple search endpoint
+            var encoded = Uri.EscapeDataString(query);
+            var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";
+            var html = await _httpClient.GetStringAsync(url, cancellationToken);
+
+            var snippets = ExtractSnippets(html);
+            if (snippets.Count == 0)
+            {
+                return $"No results found for: {query}";
+            }
+
+            return $"Search results for \"{query}\":\n" +
+                   string.Join('\n', snippets.Select((s, i) => $"{i + 1}. {s}"));
+        }
+        catch (Exception ex)
+        {
+            return $"Search failed for \"{query}\": {ex.Message}";
+        }
+    }
+
+    [Description("Save a research note. Use this to record important findings during research.")]
+    public string SaveNote(
+        [Description("The note content to save")] string content)
+    {
+        _notes.Add(content);
+        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
+        return $"Note saved. You now have {_notes.Count} note(s).";
+    }
+
+    [Description("Retrieve all saved research notes.")]
+    public string GetNotes()
+    {
+        if (_notes.Count == 0)
+        {
+            return "No notes saved yet.";
+        }
+
+        return "Saved notes:\n" +
+               string.Join('\n', _notes.Select((n, i) => $"[{i + 1}] {n}"));
+    }
+
+    public IReadOnlyList<string> GetAllNotes() => _notes.AsReadOnly();
+
+    private static List<string> ExtractSnippets(string html)
+    {
+        var snippets = new List<string>();
+
+        // Extract text from result snippet spans/table cells
+        var spans = html.Split(["<td>", "<span class=\"link-text\">"], StringSplitOptions.None);
+        foreach (var span in spans.Skip(1))
+        {
+            var endIdx = span.IndexOfAny(['<']);
+            if (endIdx <= 0) continue;
+
+            var text = System.Net.WebUtility.HtmlDecode(span[..endIdx]).Trim();
+            if (text.Length > 30 && !text.StartsWith("http", StringComparison.OrdinalIgnoreCase))
+            {
+                snippets.Add(text.Length > 300 ? text[..300] + "..." : text);
+            }
+
+            if (snippets.Count >= 8) break;
+        }
+
+        return snippets;
+    }
+}
